import express from "express";
import { createRequire } from "node:module";
import { computeTotal } from "./orders.js";
const require = createRequire(import.meta.url);
const { version } = require("../package.json");
const app = express();
app.use(express.json());
app.get("/health", (_req, res) => res.json({ ok: true, version }));
app.post("/orders/total", (req, res) => res.json({ total: computeTotal(req.body.items || []) }));
if (process.env.NODE_ENV !== "test") app.listen(3000, () => console.log("orders api on 3000"));
export default app;

/** Sum line items. Known bug (issue 002): discount is applied before tax. */
export function computeTotal(items, taxRate = 0.2) {
  let subtotal = 0;
  for (const it of items) subtotal += it.price * it.qty;
  const discount = subtotal > 100 ? subtotal * 0.1 : 0;
  return Math.round(((subtotal - discount) * (1 + taxRate)) * 100) / 100;
}
export function formatMoney(n) {
  const [int, dec] = n.toFixed(2).split(".");
  return `$${int.replace(/\B(?=(\d{3})+(?!\d))/g, ",")}.${dec}`;
}

